() => { 
  // Try to close any modal by triggering escape key
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape' }));
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape' }));
  // Also try to find close buttons
  const closeButtons = document.querySelectorAll('[aria-label*="close"], [aria-label*="Close"], [aria-label*="dismiss"], [aria-label*="Dismiss"]');
  return { 
    modalOpen: document.querySelectorAll('[role="dialog"]').length,
    closeButtons: closeButtons.length,
    bodyOverflow: getComputedStyle(document.body).overflow
  };
}

() => { 
  // Get article content
  const article = document.querySelector('article, main, [data-component="text-block"]');
  const title = document.querySelector('h1');
  const dateTime = document.querySelector('time');
  const meta = document.querySelector('meta[property="article:published_time"]');

  // Get text content from article area
  const main = document.querySelector('main') || document.body;
  const paragraphs = main.querySelectorAll('p');
  const paraTexts = Array.from(paragraphs).slice(0, 20).map(p => p.textContent.trim()).filter(t => t.length > 20);

  return {
    title: title?.textContent,
    datetime: dateTime?.getAttribute('datetime'),
    dateText: dateTime?.textContent,
    publishedMeta: meta?.getAttribute('content'),
    paragraphs: paraTexts.slice(0, 15),
    url: window.location.href
  };
}

() => { 
  // Find any element outside the modal/overlay
  const overlay = document.querySelector('[data-testid="simple-modal"]') || 
                  document.querySelector('[role="dialog"]') ||
                  document.querySelector('div[class*="overlay"]') ||
                  document.querySelector('div[class*="Overlay"]');

  // Get all divs with high z-index
  const allDivs = Array.from(document.querySelectorAll('div'));
  const overlays = allDivs.filter(d => {
    const cs = getComputedStyle(d);
    return cs.position === 'fixed' && parseInt(cs.zIndex || 0) > 100;
  });

  return {
    overlayFound: !!overlay,
    overlayCount: overlays.length,
    overlays: overlays.slice(0, 5).map(d => ({ 
      classes: d.className.toString().slice(0, 100),
      z: getComputedStyle(d).zIndex,
      hasCloseBtn: d.querySelectorAll('button').length
    }))
  };
}

() => {
  // Try to remove any modal/overlay
  const modals = document.querySelectorAll('[role="dialog"], [aria-modal="true"]');
  modals.forEach(m => m.remove());

  const overlays = Array.from(document.querySelectorAll('div')).filter(d => {
    const cs = getComputedStyle(d);
    return cs.position === 'fixed' && cs.zIndex !== 'auto' && parseInt(cs.zIndex) > 50;
  });
  overlays.forEach(o => o.remove());

  // Remove scrim
  document.body.style.overflow = 'auto';

  // Get article info
  const title = document.querySelector('h1');
  const date = document.querySelector('time');
  const main = document.querySelector('main') || document.body;
  const ps = Array.from(main.querySelectorAll('p')).map(p => p.textContent.trim()).filter(t => t.length > 30);

  return {
    title: title?.textContent,
    date: date?.textContent,
    paragraphs: ps.slice(0, 10),
    url: window.location.href,
    modalsRemoved: modals.length,
    overlaysRemoved: overlays.length
  };
}

() => { 
  // Try to remove any modal/overlay
  const modals = document.querySelectorAll('[role="dialog"], [aria-modal="true"]');
  modals.forEach(m => m.remove());

  const overlays = Array.from(document.querySelectorAll('div')).filter(d => {
    const cs = getComputedStyle(d);
    return cs.position === 'fixed' && cs.zIndex !== 'auto' && parseInt(cs.zIndex) > 50;
  });
  overlays.forEach(o => o.remove());

  // Remove scrim
  document.body.style.overflow = 'auto';

  return {
    modalsRemoved: modals.length,
    overlaysRemoved: overlays.length
  };
}
